package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeFactory._fromVariable
 */
public class TypeFactory__fromVariable_TriageGen1Test {

    private TypeFactory _typeFactory;
    private TypeVariable<?> _mockTypeVariable;
    private TypeBindings _mockContext;

    @Before
    public void setUp() {
        _typeFactory = TypeFactory.defaultInstance();
        _mockTypeVariable = mock(TypeVariable.class);
        _mockContext = mock(TypeBindings.class);
    }

    /**
     * Test case: context is null.
     * Should return _unknownType().
     */
    @Test
    public void test_fromVariable_contextNull() {
        when(_mockTypeVariable.getName()).thenReturn("T");

        // Accessing protected method via a subclass or reflection if necessary, 
        // but since we are in the same package, we can use a subclass.
        TestableTypeFactory factory = new TestableTypeFactory();
        JavaType result = factory._fromVariable(_mockTypeVariable, null);

        assertEquals(JavaType.unknownType(), result);
    }

    /**
     * Test case: context is not null, and context.findType(name) returns a valid JavaType.
     * Should return the found JavaType.
     */
    @Test
    public void test_fromVariable_contextFindsType() {
        String varName = "T";
        when(_mockTypeVariable.getName()).thenReturn(varName);
        when(_mockContext.findType(varName)).thenReturn(_typeFactory.constructSimpleType(String.class));

        TestableTypeFactory factory = new TestableTypeFactory();
        JavaType result = factory._fromVariable(_mockTypeVariable, _mockContext);

        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
        verify(_mockContext, never())._addPlaceholder(anyString());
    }

    /**
     * Test case: context is not null, context.findType(name) returns null.
     * Should add placeholder and return type constructed from the first bound.
     */
    @Test
    public void test_fromVariable_contextDoesNotFindType_usesBounds() {
        String varName = "T";
        when(_mockTypeVariable.getName()).thenReturn(varName);
        when(_mockContext.findType(varName)).thenReturn(null);

        // Mock bounds: T extends Number
        when(_mockTypeVariable.getBounds()).thenReturn(new Type[]{Number.class});

        TestableTypeFactory factory = new TestableTypeFactory();
        JavaType result = factory._fromVariable(_mockTypeVariable, _mockContext);

        // Verify placeholder was added for recursion prevention
        verify(_mockContext)._addPlaceholder(varName);

        // Verify result is constructed from the first bound (Number)
        assertNotNull(result);
        assertEquals(Number.class, result.getRawClass());
    }

    /**
     * A subclass to allow testing of protected methods of TypeFactory.
     */
    private static class TestableTypeFactory extends TypeFactory {
        protected TestableTypeFactory() {
            super(null, null);
        }

        // Expose the protected method for testing
        @Override
        protected JavaType _fromVariable(TypeVariable<?> type, TypeBindings context) {
            return super._fromVariable(type, context);
        }

        // Since _unknownType is protected, we ensure it works via the real instance logic
        // but here we just call super.
    }

    /**
     * Mocking TypeBindings is tricky because it's a complex class. 
     * In a real Jackson environment, we'd use actual TypeBindings, 
     * but for a unit test, Mockito is used to satisfy the interface/method calls.
     */
    private static class MockTypeBindings extends TypeBindings {
        protected MockTypeBindings() {
            super(null, null, null);
        }
        // Mockito handles the rest
    }
}
